#!/usr/bin/env python3
"""Generate LPDDR4 TestPlan XLSX and output base64 for GitHub API upload."""
import base64
import io
import sys
import os
from datetime import datetime, timezone, timedelta

try:
    from openpyxl import Workbook
    from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
    from openpyxl.utils import get_column_letter
except ImportError:
    import subprocess
    subprocess.check_call([sys.executable, '-m', 'pip', 'install', 'openpyxl'])
    from openpyxl import Workbook
    from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
    from openpyxl.utils import get_column_letter

IST = timezone(timedelta(hours=5, minutes=30))
now_ist = datetime.now(IST)
ts = now_ist.strftime('%Y%m%d_%H%M%S')
FILENAME = f'LPDDR4_TestPlan_{ts}.xlsx'

HF = Font(name='Calibri', bold=True, color='FFFFFF', size=11)
HB = PatternFill(start_color='4472C4', end_color='4472C4', fill_type='solid')
HA = Alignment(horizontal='center', vertical='center', wrap_text=True)
CA = Alignment(vertical='top', wrap_text=True)
BD = Border(left=Side(style='thin'), right=Side(style='thin'), top=Side(style='thin'), bottom=Side(style='thin'))

TP_COLS = ['Index','SS / Module','Feature','Test Case Name','Test Description','Speed','Mode','Memory Start Offset','Memory End Offset','Remarks','Test Steps / Procedure','Impacted Registers','Validation / Acceptance Criteria','Code Generation']
MD_COLS = ['Index','Test Case Name','Meta Test Description','Meta Test Steps / Procedure','Meta Impacted Registers','Meta Validation / Acceptance Criteria','Meta Headers','Meta Macros','Meta Arrays']

data = [
  {'Index':'1','SS / Module':'LPDDR4','Test Case Name':'lpddr4_inline_ecc_1bit_data_modify_test','Feature':'Inline ECC 1-bit Corrected Error with Data Modify','Test Description':'Verify LPDDR4 inline ECC 1-bit corrected error detection and interrupt generation across multiple ECC regions. The test configures ECC with a region map enabling regions 0, 2, 4, and 6, initializes memory via scrubber, writes random data to 7 regions, and reads back to verify that ECC-enabled regions produce corrected-error interrupts with correct data, while non-ECC regions produce data mismatches without interrupts. The final corrected error count is validated to equal 5.','Speed':'SG3200 (default); SG2667 (if SG2667 defined); SG2133 (if SG2133 defined)','Mode':'Full Bus (bus_width=0); DBI_EN=0; DM_EN=1; ECC_EN=1','Memory Start Offset':'0x80000000 (region offset base, region*0x80000000 for scrub); port1_addr: 0x15A0000000 (APS_DRAM) / 0x11A0000000 (else)','Memory End Offset':'address+0x1000 (scrub range end per region); region 6 end: 6*0x80000000 + 0x1000','Remarks':'All three Agent 2 register-access macros (SYSREG_INTR_EN_ADDR, SYSREG_INTR_MSTS_ADDR, SYSREG_INTR_RSTCR_ADDR) are conditionally defined based on APS_DRAM vs MPS compile-time selection and were unresolved by Agent 3 and Agent 4. The testcase uses ctl_base as a runtime variable for DDR controller register access with hardcoded offsets (0x70, 0x74, 0x78, 0x7c, 0x80, 0x320, 0x490, 0x540, 0xf24, 0xf28, 0xf2c, 0xf30, 0xf38, 0xf3c, 0xf40, 0xf44, 0x8194, 0x819C). The ecc_region_map=0x55 enables ECC for regions 0, 2, 4, 6 (binary 01010101). The expected corrected error count of 5 corresponds to 1 initial read of region 0 plus 4 ECC-enabled regions in the loop.','Test Steps / Procedure':'1. Enable the DDR controller interrupt via GIC and configure the system register interrupt enable for DDR controller interrupts.\n2. Perform GPV programming.\n3. Configure platform-specific base addresses for controller, PHY, and memory ports.\n4. Set bus width to full, disable DBI, enable DM and ECC, and configure speed grade.\n5. Execute LPDDR4 training sequence.\n6. Enable SBR done interrupt in the SII interrupt enable register.\n7. Disable software programming lock (SWCTL), program ECCCFG0 with ecc_region_map=0x55 and ECCCFG1 with 0x330, then re-enable the lock.\n8. For each ECC-enabled region (0, 2, 4, 6), perform memory initialization via scrubber: disable ports, configure scrub mode and interval, set scrub data pattern to zero, program scrub start/range addresses, enable scrub, wait for SBR done interrupt, reconfigure scrub parameters, and re-enable ports.\n9. Write random 64-bit data to all 7 regions (0-6) via port 1.\n10. Wait, signal training done, and wait again.\n11. Clear ECC control register, read region 0 data, poll ECCSTAT for corrected error bit, clear the corrected error, and clear the SII interrupt status.\n12. Validate that region 0 read data matches expected data.\n13. Enable both ECC corrected error and SBR done interrupts, and enable ECC corrected error interrupt in ECCCTL.\n14. For each of the 7 regions: read data, and if the region is ECC-enabled, validate data match and wait for corrected-error interrupt; if not ECC-enabled, validate data mismatch.\n15. Read ECCERRCNT and validate the corrected error count equals 5.\n16. Call finish with the error counter to determine pass or fail.','Impacted Registers':'NA','Validation / Acceptance Criteria':'1. After reading region 0, the ECC status register must indicate a corrected error (bit 8 set).\n2. Data read from ECC-enabled regions (0, 2, 4, 6) must match the originally written random data.\n3. Data read from non-ECC regions (1, 3, 5) must NOT match the originally written data.\n4. Each read from an ECC-enabled region must trigger a corrected-error interrupt, which is validated and cleared in the interrupt handler.\n5. The corrected error count register must equal 5 after all region reads.\n6. The system register masked interrupt status must correctly identify DDR controller interrupts.\n7. During scrubber initialization, the SBR done interrupt must fire and the scrub busy status must clear.\n8. The test passes if no errors are accumulated (error counter equals zero).','Meta Headers':'<stdio.h>; <stdlib.h>; "test_common.h"; "mps_sysreg.h"; "aps_sysreg.h"; "lpddr4.h"; "lpddr4_aps_sii.h"; "lpddr4_sii.h"','Meta Macros':'#define CTL_INT_NO APS_LPDDR4_CTL_INT_NO (APS_DRAM) / MPS_LPDDR4_CTL_INT_NO (else)\n#define PHY_INT_NO APS_LPDDR4_PHY_INT_NO (APS_DRAM) / MPS_LPDDR4_PHY_INT_NO (else)\n#define SYSREG_INTR_EN_ADDR MIZAR_APS_SYSREG_INTR_EN (APS_DRAM) / MIZAR_MPS_SYSREG_INTR_EN (else)\n#define SII_ECC_CORRECTED_ERR_INTR_EN_FAULT_MASK ...\n#define SII_INTR_EN_SBR_DONE_INTR_MASK ...','Meta Arrays':'unsigned long int exp_data_array[50]; /* 7 elements populated at runtime */','Meta Test Description':'This testcase validates LPDDR4 inline ECC 1-bit corrected error detection with data modification across multiple ECC regions. The test configures the DDR controller for inline ECC operation with ecc_region_map=0x55 (regions 0,2,4,6 enabled). It performs memory initialization via scrubber (SBR) for each enabled region, writes random 64-bit data to 7 regions via port1, triggers LPDDR4 training, then reads back data to verify ECC corrected-error interrupt behavior.','Meta Test Steps / Procedure':'1-38. Full ECC 1-bit corrected error test sequence with scrubber init, data write, training, read-back, interrupt validation, and ECCERRCNT check.','Meta Impacted Registers':'SYSREG_INTR_EN_ADDR; SYSREG_INTR_MSTS_ADDR; SYSREG_INTR_RSTCR_ADDR','Meta Validation / Acceptance Criteria':'1. Poll ECCSTAT until bit 8 set. 2. Validate data match for ECC regions. 3. Validate data mismatch for non-ECC regions. 4. Validate ECCERRCNT==5. 5. finish(err0) passes if err0==0.'},
  {'Index':'2','SS / Module':'LPDDR4','Test Case Name':'lpddr4_inline_ecc_2bit_data_modify_test','Feature':'Inline ECC 2-bit Uncorrected Error with Data Modify','Test Description':'Verify LPDDR4 inline ECC 2-bit uncorrected error detection, interrupt generation, and slave error behavior across multiple ECC regions. The test configures ECC with a region map enabling regions 0, 2, 4, and 6, initializes memory via scrubber, writes random data to 7 regions, and reads back to verify that ECC-enabled regions produce uncorrected-error interrupts with slave errors, and that data does not match the original writes for any region. The final uncorrected error count and slave error count are both validated to equal 5.','Speed':'SG3200 (default); SG2667 (if SG2667 defined); SG2133 (if SG2133 defined)','Mode':'Full Bus (bus_width=0); DBI_EN=0; DM_EN=1; ECC_EN=1','Memory Start Offset':'0x80000000 (region offset base, region*0x80000000 for scrub); port1_addr: 0x15A0000000 (APS_DRAM) / 0x11A0000000 (else)','Memory End Offset':'address+0x1000 (scrub range end per region); region 6 end: 6*0x80000000 + 0x1000','Remarks':'All three Agent 2 register-access macros are conditionally defined based on APS_DRAM vs MPS compile-time selection and were unresolved. This testcase differs from the 1-bit test by targeting 2-bit uncorrected ECC errors: checks ECCSTAT bit[16], uses ECCCTL bit[1] for clearing, ECCCTL bit[9] for interrupt enable, and validates uncorrected error count in ECCERRCNT bits[31:16]. Additionally expects slave errors for ECC-enabled regions.','Test Steps / Procedure':'1. Enable the DDR controller interrupt via GIC and configure the system register interrupt enable.\n2. Perform GPV programming.\n3. Configure platform-specific base addresses.\n4. Set bus width to full, disable DBI, enable DM and ECC, and configure speed grade.\n5. Execute LPDDR4 training sequence.\n6. Enable SBR done interrupt in SII.\n7. Program ECCCFG0 with ecc_region_map=0x55 and ECCCFG1 with 0x330.\n8. For each ECC-enabled region, perform memory initialization via scrubber.\n9. Write random 64-bit data to all 7 regions via port 1.\n10. Wait, signal training done, and wait again.\n11. Clear ECC control register, read region 0, poll ECCSTAT for uncorrected error bit (bit 16), clear via ECCCTL bit 1.\n12. Enable ECC uncorrected error and SBR done interrupts.\n13. For each region: read data, validate slave errors for ECC regions, validate data mismatch for ALL regions.\n14. Validate uncorrected error count (upper 16 bits) equals 5.\n15. Validate slave error count equals 5.\n16. Call finish.','Impacted Registers':'NA','Validation / Acceptance Criteria':'1. ECC status register must indicate uncorrected error (bit 16 set).\n2. Each ECC-enabled region read must trigger uncorrected-error interrupt.\n3. Each ECC-enabled region must produce a slave error.\n4. Data from all regions must NOT match original writes.\n5. Uncorrected error count must equal 5.\n6. Total slave errors must equal 5.\n7. System register masked interrupt status must be correct.\n8. SBR done interrupt must fire during scrubber init.\n9. Test passes if error counter equals zero.','Meta Headers':'<stdio.h>; <stdlib.h>; "test_common.h"; "mps_sysreg.h"; "aps_sysreg.h"; "lpddr4.h"; "lpddr4_aps_sii.h"; "lpddr4_sii.h"','Meta Macros':'#define CTL_INT_NO ... #define SII_ECC_UNCORRECTED_ERR_INTR_EN_FAULT_MASK ... #define SII_INTR_EN_SBR_DONE_INTR_MASK ...','Meta Arrays':'unsigned long int exp_data_array[50]; /* 7 elements populated at runtime */','Meta Test Description':'This testcase validates LPDDR4 inline ECC 2-bit uncorrected error detection with data modification across multiple ECC regions with ecc_region_map=0x55. Validates uncorrected-error interrupts, slave errors, and ECCERRCNT bits[31:16]==5.','Meta Test Steps / Procedure':'1-39. Full 2-bit ECC uncorrected error test sequence.','Meta Impacted Registers':'SYSREG_INTR_EN_ADDR; SYSREG_INTR_MSTS_ADDR; SYSREG_INTR_RSTCR_ADDR','Meta Validation / Acceptance Criteria':'1. Poll ECCSTAT bit 16. 2. Validate uncorrected error interrupts. 3. Validate slave errors. 4. Validate data mismatch for ALL regions. 5. Validate (ECCERRCNT>>16)==5. 6. Validate num_slverr_taken==5.'},
  {'Index':'3','SS / Module':'LPDDR4','Test Case Name':'lpddr4_mem_dm_test','Feature':'Memory Data Masking (DM)','Test Description':'Verify LPDDR4 memory data masking (DM) functionality by writing random data patterns and reading them back. The test enables DM, performs training, writes random 64-bit data to memory via port 0 and port 1, reads back via both ports to verify data integrity and cross-port coherency, and validates all read data matches the expected written data.','Speed':'SG3200 (default); SG2667 (if SG2667 defined); SG2133 (if SG2133 defined)','Mode':'Full Bus (bus_width=0); DBI_EN=0; DM_EN=1','Memory Start Offset':'port0_addr: 0 (both APS_DRAM and else); port1_addr: 0x15A0000000 (APS_DRAM) / 0x11A0000000 (else)','Memory End Offset':'Conditional block: port0_addr + 0x9000; port1_addr + 0x9000. Unconditional block: port1_addr + 0x3E0000000','Remarks':'This is a pure memory read/write test with DM enabled. No DDR controller register accesses are performed. Phase 1 is conditionally compiled. Phase 2 is unconditional with 0x20000000 (512 MB) offset spacing.','Test Steps / Procedure':'1. Perform GPV programming.\n2. Configure platform-specific base addresses.\n3. Set bus width to full, disable DBI, enable DM, and configure speed grade.\n4. Execute LPDDR4 training sequence.\n5. (Conditional) Write 10 random 64-bit data values to port 0 at 0x1000 spacing.\n6. (Conditional) Read back all 10 values from port 0 and validate.\n7. (Conditional) Read back all 10 values from port 1 (cross-port) and validate.\n8. Write 32 random 64-bit data values to port 1 at 0x20000000 spacing.\n9. Read back all 32 values from port 1 and validate.\n10. Call finish with the error counter.','Impacted Registers':'NA','Validation / Acceptance Criteria':'1. All 10 random data values written to port 0 must be correctly read back from port 0.\n2. All 10 values must also be correctly read back from port 1 (cross-port coherency).\n3. All 32 random data values written to port 1 must be correctly read back.\n4. The test passes if no data mismatches are detected.','Meta Headers':'<stdio.h>; <stdlib.h>; "test_common.h"; "lpddr4.h"','Meta Macros':'NA','Meta Arrays':'unsigned long int exp_data_array[50]; /* Two phases of runtime population */','Meta Test Description':'This testcase validates LPDDR4 memory data masking (DM) functionality with DM_EN=1, DBI_EN=0, full bus width. Two-phase memory access test with cross-port validation.','Meta Test Steps / Procedure':'1-18. Two-phase memory write/read test with cross-port validation.','Meta Impacted Registers':'NA','Meta Validation / Acceptance Criteria':'1. Phase 1: validate port0 and port1 read-back. 2. Phase 2: validate port1 read-back. 3. finish(err0) passes if err0==0.'},
  {'Index':'4','SS / Module':'LPDDR4','Test Case Name':'lpddr4_mem_half_data_bus_width_test','Feature':'Half Data Bus Width Memory Access','Test Description':'Verify LPDDR4 memory read access in half data bus width mode. The test configures the controller for half bus width, performs training, and reads data from two memory locations via port 0 (conditional) and port 1 (unconditional) to verify that the expected fixed data patterns are present in memory after training.','Speed':'SG3200 (default); SG2667 (if SG2667 defined); SG2133 (if SG2133 defined)','Mode':'Half Bus (bus_width=1); DBI_EN=0; DM_EN=0','Memory Start Offset':'port0_addr: 0 (both APS_DRAM and else); port1_addr: 0x15A0000000 (APS_DRAM) / 0x11A0000000 (else)','Memory End Offset':'port0_addr + 0x108; port1_addr + 0x108','Remarks':'This is a read-only memory verification test in half data bus width mode (bus_width=1). No data is written. DM is disabled. The validation uses logical AND (&&). No DDR controller register accesses are performed.','Test Steps / Procedure':'1. Perform GPV programming.\n2. Configure platform-specific base addresses.\n3. Set bus width to half, disable DBI and DM, and configure speed grade.\n4. Execute LPDDR4 training sequence.\n5. Signal training done and wait for stabilization.\n6. (Conditional) Read two 64-bit values from port 0 at offsets 0x100 and 0x108, validate against expected patterns.\n7. Read two 64-bit values from port 1 at offsets 0x100 and 0x108, validate against expected patterns.\n8. Call finish with the error counter.','Impacted Registers':'NA','Validation / Acceptance Criteria':'1. Data read from port 0 at offset 0x100 must equal 0x3333333333333333 or data at offset 0x108 must equal 0x2222222222222222.\n2. Data read from port 1 at offset 0x100 must equal 0x3333333333333333 or data at offset 0x108 must equal 0x2222222222222222.\n3. The test passes if no errors are accumulated.','Meta Headers':'<stdio.h>; <stdlib.h>; "test_common.h"; "lpddr4.h"','Meta Macros':'NA','Meta Arrays':'NA','Meta Test Description':'This testcase validates LPDDR4 memory access in half data bus width mode. bus_width=1, DBI_EN=0, DM_EN=0. Read-only test with fixed pattern validation.','Meta Test Steps / Procedure':'1-19. Half bus width read-only test with pattern validation.','Meta Impacted Registers':'NA','Meta Validation / Acceptance Criteria':'1. Validate port0 read using AND logic. 2. Validate port1 read using AND logic. 3. finish(err0) passes if err0==0.'}
]

wb = Workbook()
ws_tp = wb.active
ws_tp.title = 'TestPlan'
ws_tp.append(TP_COLS)
for r in data:
    ws_tp.append([r.get(c,'') if c != 'Code Generation' else '' for c in TP_COLS])

ws_md = wb.create_sheet(title='MetaData')
ws_md.append(MD_COLS)
for r in data:
    ws_md.append([r.get(c,'') for c in MD_COLS])

for ws in [ws_tp, ws_md]:
    for cell in ws[1]:
        cell.font = HF; cell.fill = HB; cell.alignment = HA; cell.border = BD
    for row in ws.iter_rows(min_row=2, max_row=ws.max_row, max_col=ws.max_column):
        for cell in row:
            cell.alignment = CA; cell.border = BD
    ws.freeze_panes = 'A2'
    for ci in range(1, ws.max_column+1):
        ml = 0
        for row in ws.iter_rows(min_col=ci, max_col=ci, values_only=False):
            for cell in row:
                if cell.value:
                    for ln in str(cell.value).split('\n'):
                        ml = max(ml, len(ln))
        ws.column_dimensions[get_column_letter(ci)].width = min(max(ml+2, 12), 60)

ws_md.sheet_state = 'veryHidden'

buf = io.BytesIO()
wb.save(buf)
wb.close()
buf.seek(0)

# Also save to file
SCRIPT_DIR = os.path.dirname(os.path.abspath(__file__))
OUTPUT_PATH = os.path.join(SCRIPT_DIR, FILENAME)
with open(OUTPUT_PATH, 'wb') as f:
    f.write(buf.getvalue())

print(f'FILENAME={FILENAME}')
print(f'SIZE={len(buf.getvalue())}')
print(f'PATH={OUTPUT_PATH}')

# Output base64 for GitHub API
b64 = base64.b64encode(buf.getvalue()).decode('ascii')
print(f'BASE64_START')
print(b64)
print(f'BASE64_END')
